*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:16px/1.5 ui-sans-serif,system-ui,sans-serif}::selection{background:var(--accent);color:var(--deep)}:focus-visible{outline:3px solid #bd2670;outline-offset:4px}a{color:inherit;text-underline-offset:4px}button,input,select{font:inherit}button,select{min-height:46px}button{cursor:pointer}button:disabled{cursor:default;opacity:.55}.controls :focus-visible{outline-color:var(--accent)}button:hover:not(:disabled){filter:brightness(.94)}input{accent-color:var(--accent);caret-color:var(--blue)}html{scrollbar-color:var(--blue) var(--ground)}
